DB::table("products")->join("categories","categories.id","=","products.category_id")->whereIn("categories.name",["Res","Pollo"])->where("products.active",1)->select("products.name","products.price_per_kg_usd","products.location","products.branch_id","categories.name as cat")->orderBy("cat")->orderBy("products.name")->get()->each(function($p){echo $p->cat." | br=".$p->branch_id." | ".$p->location." | ".$p->name." | USD ".$p->price_per_kg_usd.chr(10);});
